macroData.command:
const pass = args[0]?.macroPass;
if (pass !== "postPreambleComplete" && pass !== "postActiveEffects") return;

const marker = "flags.dnd5e_classpack.nathair";
const combat = game.combat;
const turnKey = combat?.active ? `${combat.id}.${combat.round}.${combat.turn}` : null;
const socket = MidiQOL.socket();
const resolve = uuid => uuid ? fromUuid(uuid) : null;

const updateRegion = (region, update, behaviors) => game.user.isGM
  ? (async () => {
    if (update) await region.update(update);
    if (behaviors?.length) {
      await region.createEmbeddedDocuments("RegionBehavior", behaviors);
    }
  })()
  : socket.executeAsGM("setupRegion", { regionUuid: region.uuid, update, behaviors });

if (pass === "postPreambleComplete") {
  const prepared = await prepare();
  if (!prepared) return;

  workflow._nathairPrepared = prepared;
  // Midi 14.6.11 的通用自动掷骰沿用自动伤害开关。
  workflow.workflowOptions.autoRollDamage = "onHit";
  return;
}

const prepared = workflow._nathairPrepared;
if (!prepared) return;
delete workflow._nathairPrepared;

const { item } = prepared;
let { state } = prepared;
const region = await resolve(prepared.regionUuid);

if (!region || !canvas.ready || canvas.scene?.id !== region.parent?.id ||
    region.flags?.dnd5e_classpack?.nathair?.turnKey !== state.turnKey ||
    (state.turnKey !== null && turnKey !== state.turnKey)) return;

const result = workflow.utilityRoll?.total;
if (![1, 2, 3, 4].includes(result)) return;

// 只绑定本次施法新应用的自施 AE。
const anchors = Array.from(workflow.actor.effects).filter(effect =>
  effect.active && !effect.duration?.expired &&
  !prepared.priorEffectIds.has(effect.id) &&
  Array.from(effect.system?.changes ?? []).some(change =>
    change.key === "flags.midi-qol.ActivityOverTime" &&
    change.value === "nathair-repeat"
  )
);

if (anchors.length !== 1) {
  ui.notifications.warn(
    "纳撒尔恶作剧：找不到本次施法新应用的自施 OverTime AE，请检查主活动的效果列表和 DAE 自施设置。"
  );
  return;
}

const [anchor] = anchors;
state = { ...state, anchorUuid: anchor.uuid };
await updateRegion(region, {
  [marker]: state,
  "flags.dnd5e.dependentOn": anchor.uuid
});

const descriptions = [
  "苹果派香气：感知豁免，失败则魅惑。",
  "鲜花喷水：敏捷豁免，失败则目盲。",
  "咯咯笑：感知豁免，失败则失能并随机移动。",
  "悬浮蜜糖：区域成为困难地形。"
];
state = { ...state, result, actors: [] };

if (result === 4) {
  const terrain = region.behaviors.find(b => b.flags?.dnd5e_classpack?.nathairTerrain);
  await updateRegion(region, {
    [marker]: state,
    ...(terrain ? { behaviors: [{ _id: terrain.id, disabled: false }] } : {})
  });
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: item.actor }),
    content: `恶作剧之涌（4）：${descriptions[3]}`
  });
  return;
}

const priorTargetIds = Array.from(game.user.targets ?? [], target => target.id);
const targets = MidiQOL.selectTargetsFromTemplates(
  [region.uuid], state.casterTokenUuid ?? "", false, "any", "always"
);
const selectedIds = new Set(targets.map(target => target.id));

try {
  state.actors = [...new Set(targets.map(target => target.actor?.uuid).filter(Boolean))];
  await updateRegion(region, { [marker]: state });
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: item.actor }),
    content: `恶作剧之涌（${result}）：${descriptions[result - 1]}`
  });
  if (!targets.length) return;

  const baseSave = item.system.activities.find(a => a.identifier === "nathair-save");
  if (!baseSave) {
    ui.notifications.warn("纳撒尔恶作剧：未找到 Identifier 为 nathair-save 的豁免活动。");
    return;
  }

  const ability = result === 2 ? "dex" : "wis";
  const rolledItem = item.clone({
    system: { activities: { [baseSave.id]: { save: { ability: [ability] } } } }
  }, { keepId: true });
  const save = rolledItem.system.activities.get(baseSave.id);

  await MidiQOL.completeActivityUse(save, { midiOptions: {
    targetsToUse: new Set(targets),
    checkGMstatus: false,
    ignoreUserTargets: true,
    workflowOptions: {
      targetConfirmation: "none",
      noProvokeReaction: true,
      allowIncapacitated: true,
      nathairRegionUuid: region.uuid,
      nathairTurnKey: turnKey
    }
  } }, { configure: false }, { create: true });
} finally {
  if (canvas.scene?.id === region.parent?.id) {
    const currentIds = new Set(Array.from(game.user.targets ?? [], target => target.id));
    if (currentIds.size === selectedIds.size && [...currentIds].every(id => selectedIds.has(id))) {
      canvas.tokens?.setTargets(priorTargetIds);
    }
  }
}

async function prepare() {
  const item = workflow.item;
  let region;
  for (const uuid of workflow.templateUuids ?? []) {
    const doc = await resolve(uuid);
    if (doc?.documentName === "Region") {
      region = doc;
      break;
    }
  }
  if (!region || region.flags?.dnd5e_classpack?.nathair) return;

  const casterTokenUuid = workflow.token?.document?.uuid ?? workflow.tokenUuid;
  const state = { itemUuid: item.uuid, casterTokenUuid, anchorUuid: null, turnKey, actors: [] };

  const config = workflow.activity.regionBehavior;
  if (!config?.enabled || config.rules?.length || Number(config.moveDistance ?? 0) > 0) {
    ui.notifications.warn(
      "纳撒尔恶作剧：请开启施法活动的 Region Behavior，将自动移动距离设为 0，并清空规则列表。"
    );
    return;
  }

  await updateRegion(region, { [marker]: state }, [{
    name: "恶作剧之涌：蜜糖",
    type: "dnd5e.difficultTerrain",
    disabled: true,
    flags: { dnd5e_classpack: { nathairTerrain: true } },
    system: { magical: true, types: [], ignoredDispositions: [] }
  }]);

  region = await resolve(region.uuid);
  if (!region) return;
  if (!canvas.ready || canvas.scene?.id !== region.parent?.id) {
    ui.notifications.warn("纳撒尔恶作剧：请在区域所在的场景里结算。");
    return;
  }

  return {
    item, state, regionUuid: region.uuid,
    priorEffectIds: new Set(Array.from(workflow.actor.effects, effect => effect.id))
  };
}

const pass = args[0]?.macroPass;
if (pass !== "postPreambleComplete" && pass !== "postUtilityRollComplete") return;

const marker = "flags.dnd5e_classpack.nathair";
const combat = game.combat;
const turnKey = combat?.active ? `${combat.id}.${combat.round}.${combat.turn}` : null;
const socket = MidiQOL.socket();
const resolve = uuid => uuid ? fromUuid(uuid) : null;

const isActive = async uuid => {
  const anchor = await resolve(uuid);
  return !!anchor?.active && !anchor.duration?.expired;
};

const updateRegion = (region, update) => game.user.isGM
  ? region.update(update)
  : socket.executeAsGM("setupRegion", { regionUuid: region.uuid, update });

if (pass === "postPreambleComplete") {
  const prepared = await prepare();
  if (!prepared) {
    workflow.aborted = true;
    return;
  }

  workflow._nathairPrepared = prepared;
  workflow.workflowOptions.autoRollDamage = "onHit";
  return;
}

const prepared = workflow._nathairPrepared;
if (!prepared) return;
delete workflow._nathairPrepared;

const { item } = prepared;
let { state } = prepared;
const region = await resolve(prepared.regionUuid);

if (!region || !canvas.ready || canvas.scene?.id !== region.parent?.id ||
    !await isActive(state.anchorUuid) ||
    region.flags?.dnd5e_classpack?.nathair?.turnKey !== state.turnKey ||
    (state.turnKey !== null && turnKey !== state.turnKey)) return;

const result = workflow.utilityRoll?.total;
if (![1, 2, 3, 4].includes(result)) return;

const descriptions = [
  "苹果派香气：感知豁免，失败则魅惑。",
  "鲜花喷水：敏捷豁免，失败则目盲。",
  "咯咯笑：感知豁免，失败则失能并随机移动。",
  "悬浮蜜糖：区域成为困难地形。"
];
state = { ...state, result, actors: [] };

if (result === 4) {
  const terrain = region.behaviors.find(b => b.flags?.dnd5e_classpack?.nathairTerrain);
  await updateRegion(region, {
    [marker]: state,
    ...(terrain ? { behaviors: [{ _id: terrain.id, disabled: false }] } : {})
  });
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: item.actor }),
    content: `恶作剧之涌（4）：${descriptions[3]}`
  });
  return;
}

const priorTargetIds = Array.from(game.user.targets ?? [], target => target.id);
const targets = MidiQOL.selectTargetsFromTemplates(
  [region.uuid], state.casterTokenUuid ?? "", false, "any", "always"
);
const selectedIds = new Set(targets.map(target => target.id));

try {
  state.actors = [...new Set(targets.map(target => target.actor?.uuid).filter(Boolean))];
  await updateRegion(region, { [marker]: state });
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: item.actor }),
    content: `恶作剧之涌（${result}）：${descriptions[result - 1]}`
  });
  if (!targets.length) return;

  const baseSave = item.system.activities.find(a => a.identifier === "nathair-save");
  if (!baseSave) {
    ui.notifications.warn("纳撒尔恶作剧：未找到 Identifier 为 nathair-save 的豁免活动。");
    return;
  }

  const ability = result === 2 ? "dex" : "wis";
  const rolledItem = item.clone({
    system: { activities: { [baseSave.id]: { save: { ability: [ability] } } } }
  }, { keepId: true });
  const save = rolledItem.system.activities.get(baseSave.id);

  await MidiQOL.completeActivityUse(save, { midiOptions: {
    targetsToUse: new Set(targets),
    checkGMstatus: false,
    ignoreUserTargets: true,
    workflowOptions: {
      targetConfirmation: "none",
      noProvokeReaction: true,
      allowIncapacitated: true,
      nathairRegionUuid: region.uuid,
      nathairTurnKey: turnKey
    }
  } }, { configure: false }, { create: true });
} finally {
  if (canvas.scene?.id === region.parent?.id) {
    const currentIds = new Set(Array.from(game.user.targets ?? [], target => target.id));
    if (currentIds.size === selectedIds.size && [...currentIds].every(id => selectedIds.has(id))) {
      canvas.tokens?.setTargets(priorTargetIds);
    }
  }
}

async function prepare() {
  const tick = await resolve(workflow.workflowOptions?.overTimeEffectUuid);
  const token = combat?.combatant?.token;
  if (!turnKey || !tick?.active || tick.duration?.expired ||
      !token?.actor || token.actor.uuid !== tick.parent?.uuid) return;

  const origin = tick.system?.origin;
  const castActivity = await resolve(origin?.activity);
  const item = castActivity?.item
    ?? await resolve(origin?.item)
    ?? await resolve(workflow.item.uuid);
  if (!item?.system?.activities || item.actor?.uuid !== token.actor.uuid) return;

  const regions = Array.from(token.parent?.regions ?? []).filter(region => {
    const state = region.flags?.dnd5e_classpack?.nathair;
    return state?.itemUuid === item.uuid &&
      (!state.casterTokenUuid || state.casterTokenUuid === token.uuid) &&
      state.anchorUuid === tick.uuid;
  });
  if (regions.length !== 1) return;

  let [region] = regions;
  let state = region.flags.dnd5e_classpack.nathair;
  if (state.turnKey === turnKey || !await isActive(state.anchorUuid)) return;

  // 登记本回合，清理上一轮的困难地形和受术状态。
  const previousActors = state.actors;
  state = { ...state, turnKey, result: null, actors: [] };
  await updateRegion(region, { [marker]: state });

  const terrain = region.behaviors.find(b => b.flags?.dnd5e_classpack?.nathairTerrain);
  if (terrain && !terrain.disabled) {
    await updateRegion(region, { behaviors: [{ _id: terrain.id, disabled: true }] });
  }

  for (const uuid of previousActors) {
    const actor = await resolve(uuid);
    if (!actor) continue;
    const effects = Array.from(actor.effects)
      .filter(e => e.flags?.dnd5e_classpack?.nathairResult === region.uuid)
      .map(e => e.id);
    if (effects.length) await MidiQOL.removeEffects({ actorUuid: actor.uuid, effects });
  }

  const stillCurrent = async () =>
    `${game.combat?.id}.${game.combat?.round}.${game.combat?.turn}` === turnKey &&
    await isActive(state.anchorUuid);

  region = await resolve(region.uuid);
  if (!region || !await stillCurrent()) return;
  if (!canvas.ready || canvas.scene?.id !== region.parent?.id) {
    ui.notifications.warn("纳撒尔恶作剧：请在战斗所在的场景里结算。");
    return;
  }

  const directions = {
    n: [0, -1], ne: [1, -1], e: [1, 0], se: [1, 1],
    s: [0, 1], sw: [-1, 1], w: [-1, 0], nw: [-1, -1]
  };

  const choice = await foundry.applications.api.DialogV2.wait({
    window: { title: "纳撒尔恶作剧：重掷前移动区域" },
    content: `
      <p><label>方向 <select name="direction">
        <option value="n">北</option><option value="ne">东北</option>
        <option value="e">东</option><option value="se">东南</option>
        <option value="s">南</option><option value="sw">西南</option>
        <option value="w">西</option><option value="nw">西北</option>
      </select></label></p>
      <p><label>距离（尺）
        <input name="distance" type="number" min="0" max="10" step="any" value="10">
      </label></p>`,
    buttons: [
      {
        action: "move",
        label: "移动并重掷",
        callback: (_event, _button, dialog) => ({
          direction: dialog.element.querySelector('[name="direction"]').value,
          distance: dialog.element.querySelector('[name="distance"]').valueAsNumber
        })
      },
      { action: "stay", label: "原地重掷", default: true, callback: () => null }
    ],
    rejectClose: false
  });

  if (!await stillCurrent()) return;
  region = await resolve(region.uuid);
  if (!region) return;

  const direction = Object.hasOwn(directions, choice?.direction)
    ? directions[choice.direction] : null;
  const distance = Number.isFinite(choice?.distance)
    ? Math.max(0, Math.min(10, choice.distance)) : 0;

  if (direction && distance > 0) {
    const scene = region.parent;
    const [x, y] = direction;
    const pixels = distance * scene.dimensions.distancePixels;
    const length = Math.hypot(x, y);
    const dx = x * pixels / length;
    const dy = y * pixels / length;

    const shapes = region.shapes.map(shape => {
      const shifted = shape.clone({}, { parent: scene });
      shifted.move({ x: shape.origin.x + dx, y: shape.origin.y + dy });
      return shifted.toObject();
    });

    await updateRegion(region, { shapes });
    region = await resolve(region.uuid);
  }

  if (!region || !await stillCurrent()) return;
  if (!canvas.ready || canvas.scene?.id !== region.parent?.id) {
    ui.notifications.warn("纳撒尔恶作剧：请在区域所在的场景里结算。");
    return;
  }

  return { item, state, regionUuid: region.uuid };
}

if (args[0] === "each") {
  // DAE 在咯咯笑生物自己的回合开始时调用。
  if (lastArgValue.turn !== "startTurn" || !effect?.active) return;

  const combatant = game.combat?.combatant;
  const state = effect.flags?.dnd5e_classpack;
  const source = state?.nathairSourceToken;
  if (!combatant?.token ||
      combatant.token.uuid !== state?.nathairAffectedToken ||
      combatant.token.uuid === source) return;

  const direction = await new Roll("1d8").evaluate();
  const directions = ["北", "东北", "东", "东南", "南", "西南", "西", "西北"];
  await direction.toMessage({
    speaker: ChatMessage.getSpeaker({ token: combatant.token }),
    flavor: `咯咯笑：本回合用可用移动力向${directions[direction.total - 1]}移动，遇到障碍时在可到达的位置停下。`
  });
  return;
}

if (args[0]?.macroPass === "preItemRoll") {
  return !!workflow.workflowOptions?.nathairRegionUuid;
}
if (args[0]?.macroPass !== "postSave") return;

const region = await fromUuid(workflow.workflowOptions?.nathairRegionUuid);
const state = region?.flags?.dnd5e_classpack?.nathair;

const isActive = async uuid => {
  const anchor = uuid ? await fromUuid(uuid) : null;
  return !!anchor?.active && !anchor.duration?.expired;
};

if (!state ||
    state.turnKey !== workflow.workflowOptions.nathairTurnKey ||
    !await isActive(state.anchorUuid)) return;

const status = ({ 1: "charmed", 2: "blinded", 3: "incapacitated" })[state.result];
if (!status) return;

const names = {
  charmed: "苹果派香气：魅惑",
  blinded: "鲜花喷水：目盲",
  incapacitated: "咯咯笑：失能"
};
const laughing = status === "incapacitated";

const failed = new Map();
for (const target of workflow.failedSaves ?? []) {
  if (!target.actor) continue;
  const alreadyApplied = Array.from(target.actor.effects).some(e =>
    e.flags?.dnd5e_classpack?.nathairResult === region.uuid && e.statuses.has(status)
  );
  if (!alreadyApplied) failed.set(target.actor.uuid, target);
}

for (const token of failed.values()) {
  if (!await isActive(state.anchorUuid)) break;

  const actor = token.actor;
  if (actor.system?.traits?.ci?.value?.has?.(status)) continue;

  const data = {
    name: `纳撒尔恶作剧：${names[status]}`,
    img: workflow.item.img,
    transfer: false,
    statuses: [status],
    duration: { units: "seconds", value: null, expiry: "sourceStart" },
    system: {
      origin: {
        actor: workflow.actor.uuid,
        item: workflow.item.uuid,
        activity: workflow.activity.uuid
      },
      changes: laughing ? [{
        key: "macro.activityMacro",
        value: workflow.activity.uuid,
        type: "custom",
        phase: "initial",
        priority: 20,
        replacement: ""
      }] : []
    },
    flags: {
      dnd5e: { dependentOn: state.anchorUuid },
      ...(laughing ? { dae: { macroRepeat: "startEveryTurn" } } : {}),
      dnd5e_classpack: {
        nathairResult: region.uuid,
        nathairSourceToken: state.casterTokenUuid,
        nathairAffectedToken: token.document?.uuid ?? token.uuid
      }
    }
  };

  if (game.user.isGM) {
    await actor.createEmbeddedDocuments("ActiveEffect", [data]);
  } else {
    await MidiQOL.socket().executeAsGM("createEffects", {
      actorUuid: actor.uuid, effects: [data]
    });
  }
}
